import {parseResearchBackup} from './persistence.js';
import {Map as MapLibreMap,Popup,setWorkerUrl} from 'maplibre-gl';
import workerUrl from 'maplibre-gl/dist/maplibre-gl-worker.mjs?worker&url';
import 'maplibre-gl/dist/maplibre-gl.css';
import './style.css';
import './upgrade.css';
import {icon,hydrateIcons} from './icons.js';
import {DEFAULT_PREFS,validPreferences,normalizePreferences,rateAMD,estimate,offerMatches,matchInfo,filterProjects,hasCoordinates,features,csvCell,escapeHTML as e,safeURL,targetEnd} from './model.js';
import {t,tr,projectText,number,money,million,date,setLanguage,getLanguage,loadTranslations,translateDOM} from './i18n.js';
import {distanceKm,costScenario,catalogueStats,radiusGeoJSON,modelHitFeature} from './analysis.js';
import {applySpatialData,spatialStats,footprintMetrics,geometryBounds,migrateModel,rectangleRing} from './geo.js';
import {spatialSection,spatialLocationLabel} from './spatial-ui.js';
import {FILTER_DEFAULTS,normalizeFilters,searchMatchInfo,projectPasses,matchingOfferEntries,searchProjects,facetCounts,needsUnit,searchPayload,parseSearch,unavailable} from './filters.js';
import {filterDialogHTML,readFilterForm,activeFilterItems,freshnessHTML,matchingEvidenceHTML} from './filter-ui.js';
import './filters.css';
setWorkerUrl(workerUrl);
const $=id=>document.getElementById(id),STORE='yerevan-atlas-v1';
let cached={};try{cached=JSON.parse(localStorage.getItem(STORE)||'{}');}catch{}
if(!cached||typeof cached!=='object'||Array.isArray(cached))cached={};
let prefs=normalizePreferences(cached.prefs)||normalizePreferences();
const state={query:'',district:'',status:'',sort:'match',view:'explore',match:false,preferred:false,offers:false,saved:new Set(Array.isArray(cached.saved)?cached.saved:[]),compare:new Set(Array.isArray(cached.compare)?cached.compare.slice(0,4):[]),notes:cached.notes&&typeof cached.notes==='object'?cached.notes:{},checks:cached.checks&&typeof cached.checks==='object'?cached.checks:{},reference:Array.isArray(cached.reference)&&cached.reference.length===2&&cached.reference.every(Number.isFinite)?cached.reference:null,selected:null,selectedBuilding:null,footprintsOnly:false,tab:'overview',is3d:true};
let filters=normalizeFilters(cached.filters),savedSearches=Array.isArray(cached.savedSearches)?cached.savedSearches.filter(s=>typeof s.name==='string'&&parseSearch(s.search)).slice(0,20):[];
setLanguage(cached.locale||'hy');
let projects=[],filtered=[],metadata={},presets=[],modelRecords=new globalThis.Map(),map=null,mapReady=false,mapModels=null,mapModelsLoading=null,popup=null,hoverPopup=null,toastTimer,referenceMode=false;
let matchEntryCache=new globalThis.Map(),matchInfoCache=new globalThis.Map(),visibleLimit=30,lastResultSignature='',searchTimer;
const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const nm=p=>projectText(p,'name'),address=p=>projectText(p,'address');
const statusLabel=p=>t(p.status==='completed'?'Reported complete':p.status==='under_construction'?'Under construction':'Status unverified');
const pinLabel=spatialLocationLabel;
const priceLabel=p=>!rateAMD(p,prefs)?t('Price on enquiry'):p.price.currency==='AMD'?money(p.price.min):new Intl.NumberFormat({hy:'hy-AM',ru:'ru-RU',en:'en-GB'}[getLanguage()],{style:'currency',currency:p.price.currency,maximumFractionDigits:0}).format(p.price.min);
const priceRange=p=>priceLabel(p)+(rateAMD(p,prefs)&&p.price?.max&&p.price.max!==p.price.min?'–'+number(p.price.max,0):'');
const link=(url,label,klass='')=>`<a class="${klass}" href="${e(safeURL(url))}" target="_blank" rel="noopener noreferrer">${e(label)} ${icon('external')}</a>`;
function persist(){try{localStorage.setItem(STORE,JSON.stringify({prefs,saved:[...state.saved],compare:[...state.compare],notes:state.notes,checks:state.checks,locale:getLanguage(),reference:state.reference,filters,savedSearches}));}catch{toast(t('Could not save locally. Export a research backup.'));}}
function toast(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,4500);}
function download(content,type,filename){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function showDialog(id){const d=$(id);if(typeof d.showModal==='function')d.showModal();else d.setAttribute('open','');}
function showInfo(title,html){$('infoTitle').textContent=title;$('infoContent').innerHTML=html;showDialog('infoDialog');}
function currentMatch(p){if(!matchInfoCache.has(p.id))matchInfoCache.set(p.id,projectPasses(p,{...state,view:'explore'},prefs,filters,Date.now(),matchEntryCache)?searchMatchInfo(p,prefs,filters,unitEntries(p)):{level:'outside',label:'Does not match current search'});return matchInfoCache.get(p.id);}
function fitBadge(p){const m=currentMatch(p);return `<span class="fit-badge ${m.level}">${icon(m.level==='offer'?'check':'info')}${e(t(m.label))}</span>`;}
function projectImage(p,klass,index=0){const url=p.imageSourceUrls?.[index];return url?`<img class="${klass}" src="${e(safeURL(url))}" alt="${e(nm(p))}" loading="lazy" referrerpolicy="no-referrer"/>`:`<span class="${klass} card-placeholder">${icon('building')}</span>`;}
function sourceLink(s){let host='';try{host=new URL(s.url).hostname.replace('www.','');}catch{}return `<a class="source-link" href="${e(safeURL(s.url))}" target="_blank" rel="noopener noreferrer"><span><strong>${e(host)}</strong><small>${e(sourceType(s.type))} · ${s.checkedAt?e(t('Checked {date}',{date:date(s.checkedAt,true)})):e(t('Link supplied by publisher'))}</small></span>${icon('external')}</a>`;}
function sourceType(type){return t(/developer|official|operator|contractor/.test(type||'')?'Developer / operator':/unit|apartment/.test(type||'')?'Apartment listing':'Published source');}
function unitEntries(p){if(!matchEntryCache.has(p.id))matchEntryCache.set(p.id,matchingOfferEntries(p,prefs,filters));return matchEntryCache.get(p.id);}
function renderCard(p){const entries=unitEntries(p),count=entries.length,cheapest=entries.reduce((a,b)=>!a||b.budgetPrice<a.budgetPrice?b:a,null);const distance=distanceKm(state.reference,p.coordinates);return `<article class="project-card ${state.selected===p.id?'selected':''}" data-project="${e(p.id)}"><button class="card-main" data-open="${e(p.id)}" aria-label="${e(t('Open {name}',{name:nm(p)}))}">${projectImage(p,'card-image')}<div class="card-content"><div class="card-district">${e(t(p.district))}${distance!=null?' · '+number(distance)+' '+t('km'):''}</div><h3>${e(nm(p))}</h3><p class="card-address">${e(address(p))}</p><div class="card-price">${cheapest?million(cheapest.budgetPrice):priceLabel(p)} <small>${cheapest?e(t(filters.budgetBasis==='total'?'matching apartment with extras from':'matching apartment from')):p.price?.min?e(t('from / m²')):''}</small></div><div class="card-evidence">${count?e(t('{n} matching offers',{n:number(count,0)})):e(statusLabel(p))}</div>${cheapest?`<div class="card-unit-proof">${number(cheapest.offer.area)} ${t('m²')} · ${cheapest.offer.rooms?t('{n} rooms',{n:cheapest.offer.rooms})+' · ':''}${cheapest.offer.floor!=null?t('Floor {n}',{n:cheapest.offer.floor}):t('Floor not published')}</div>`:''}</div></button><button class="card-save ${state.saved.has(p.id)?'active':''}" data-save="${e(p.id)}" aria-label="${e(t(state.saved.has(p.id)?'Unsave':'Save project'))}" aria-pressed="${state.saved.has(p.id)}">${icon('heart')}</button>${freshnessHTML(p)}<div class="card-bottom">${fitBadge(p)}<button class="compare-small ${state.compare.has(p.id)?'active':''}" data-compare="${e(p.id)}" aria-pressed="${state.compare.has(p.id)}">${icon('compare')}${t('Compare')}</button></div></article>`;}
function renderResults(){
 const signature=JSON.stringify([state.query,state.sort,state.view,state.reference,filters,prefs,getLanguage()]);
 if(signature!==lastResultSignature){visibleLimit=30;lastResultSignature=signature;$('resultsList').scrollTop=0;}
 matchEntryCache.clear();matchInfoCache.clear();
 filtered=searchProjects(projects,state,prefs,filters,Date.now(),matchEntryCache);
 if(state.sort==='name')filtered.sort((a,b)=>nm(a).localeCompare(nm(b),getLanguage()));if(state.sort==='distance')filtered.sort((a,b)=>(distanceKm(state.reference,a.coordinates)??Infinity)-(distanceKm(state.reference,b.coordinates)??Infinity));
 $('resultCount').textContent=t('{n} projects',{n:number(filtered.length,0)});$('resultsList').innerHTML=filtered.length?filtered.slice(0,visibleLimit).map(renderCard).join('')+resultsPagination():`<div class="empty-state">${icon('home')}<h3>${t(state.view==='saved'?'Your shortlist starts here.':'No projects match yet.')}</h3><p>${t(state.view==='saved'?'Save projects with the heart button. Notes stay on this device.':'No listing satisfies every selected criterion. Try one of these changes.')}</p>${relaxSuggestions()}<button class="button light" data-reset>${t('Reset filters')}</button></div>`;
 if($('moreProjects'))$('moreProjects').onclick=()=>{visibleLimit+=30;renderResults();$('moreProjects')?.focus();};
 const stats=catalogueStats(filtered,prefs);stats.offers=filtered.reduce((n,p)=>n+unitEntries(p).length,0);$('insightStrip').innerHTML=`<div><strong>${number(stats.offers,0)}</strong><small>${t('published unit matches')}</small></div><div><strong>${stats.median?money(stats.median):'—'}</strong><small>${t('median starting rate / m²')}</small></div><button id="insightAbout" aria-label="${e(t('About these numbers'))}">${icon('info')}</button>`;
 $('dataHealthButton').textContent=t('Data health · {n} source conflicts',{n:number(evidenceSummary(filtered).conflicts,0)});
 $('insightAbout').onclick=()=>showInfo(t('About these numbers'),`<p>${t('The median uses published starting rates for the filtered records. It is not a median transaction price. Separate source inventories may describe the same complex.')}</p><p>${t('Apartment counts follow your active filters. Booked units are excluded unless you explicitly include them. A source snapshot is not live availability.')}</p>`);
 $('mapProjectCount').textContent=number(filtered.filter(hasCoordinates).length,0);$('footprintCount').textContent=t('{n} mapped building footprints',{n:number(spatialStats(filtered).buildings,0)});$('mapSubheading').textContent=filters.districts.length?filters.districts.map(t).join(' · '):t('New residential developments');$('preferenceSummary').textContent=number(prefs.areaMin)+'–'+number(prefs.areaMax)+' '+t('m²')+' · '+number(prefs.budgetMin)+'–'+number(prefs.budgetMax)+' '+t('million AMD');
 $('savedCount').textContent=number(state.saved.size,0);$('compareCount').textContent=number(state.compare.size,0);$('matchToggle').setAttribute('aria-pressed',filters.useBudget&&filters.useArea);$('preferredToggle').setAttribute('aria-pressed',filters.districts.length===2&&filters.districts.includes('Ajapnyak')&&filters.districts.includes('Arabkir'));$('offersToggle').setAttribute('aria-pressed',filters.mode==='units');document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));
 $('sortSelect').querySelector('[value="distance"]').disabled=!state.reference;renderActiveFilters();renderTray();updateMap();
}
function resultsPagination(){return `<div class="result-pagination"><p>${t('Showing {shown} of {total} projects. The map includes every match.',{shown:number(Math.min(visibleLimit,filtered.length),0),total:number(filtered.length,0)})}</p>${visibleLimit<filtered.length?`<button id="moreProjects" class="button light full">${t('Show more projects')}</button>`:''}</div>`;}
function refreshSearchResults(){renderResults();if(state.selected)renderDetail(projects.find(p=>p.id===state.selected));if($('compareDialog').open)showComparison();}
function renderTray(){const list=[...state.compare].map(id=>projects.find(p=>p.id===id)).filter(Boolean);$('compareTray').hidden=!list.length;$('trayTitle').textContent=t('{n} of 4 selected',{n:number(list.length,0)});$('trayNames').textContent=list.map(nm).join(' · ');$('openCompare').disabled=list.length<2;}
function toggleSave(id){state.saved.has(id)?state.saved.delete(id):state.saved.add(id);persist();renderResults();if(state.selected===id)renderDetail(projects.find(p=>p.id===id));}
function toggleCompare(id){if(state.compare.has(id))state.compare.delete(id);else if(state.compare.size<4)state.compare.add(id);else return toast(t('Select up to four projects.'));persist();renderResults();if(state.selected===id)renderDetail(projects.find(p=>p.id===id));}
function fact(label,value){return `<div class="fact"><small>${e(t(label))}</small><strong>${value}</strong></div>`;}
function sourceNotes(p){return (p.notes||[]).map(n=>`<div class="note-box">${e(tr(n))}</div>`).join('');}
function modelType(p){return t(modelRecords.get(p.id)?.preset?'Image-based approximation':modelRecords.has(p.id)?'Your saved 3D model':p.spatial?.footprints?.length?'Mapped building footprint':'Point only — dimensions unknown');}
function renderCost(p){const c=costScenario(p,prefs,filters);if(!c)return `<div class="scenario-box"><h3>${t('Total-cost scenario')}</h3><p>${t('A current unit quote is needed for a cost scenario.')}</p></div>`;return `<div class="scenario-box cost-scenario"><div class="scenario-top"><strong>${t('Total-cost scenario')}</strong><span>${number(c.area)} ${t('m²')}</span></div><div class="scenario-value">${million(c.total)}</div><div class="cost-breakdown"><div><span>${t('Apartment purchase')}</span><b>${million(c.purchase)}</b></div><div><span>${t('Renovation')}</span><b>${million(c.renovation)}</b></div><div><span>${t('Parking')}</span><b>${million(c.parking)}</b></div><div><span>${t('Other fees')}</span><b>${million(c.fees)}</b></div></div><p>${t(c.offer?'Purchase uses the lowest captured matching offer; financing conditions may apply.':'Purchase is a starting-rate estimate at the scenario area, not a unit quote.')}</p><button class="text-link" data-preferences>${t('Edit cost assumptions')}</button></div>`;}
function overview(p){const est=estimate(p,prefs),m=matchInfo(p,prefs),past=p.completion&&targetEnd(p.completion)!=null&&targetEnd(p.completion)<Date.now()&&p.status!=='completed';const dist=distanceKm(state.reference,p.coordinates);return `<section class="detail-section"><div class="section-heading"><h3>${t('Published price')}</h3>${fitBadge(p)}</div><div class="price-hero">${priceRange(p)} <small>${p.price?.min?t('/ m²'):''}</small></div><p class="field-help">${p.priceNote?e(tr(p.priceNote)):t('Price depends on the apartment, floor, view and payment terms.')}</p>${p.soldOut?`<div class="note-box">${t('A source marks this project sold out. Published prices are reference only.')}</div>`:''}<div class="budget-line"><span>${t('Your size scenario')}</span><b>${est?million(est.min)+'–'+million(est.max):t('Quote needed')}</b></div><p class="field-help">${e(unitEntries(p).length?t('{n} published apartments meet all selected criteria',{n:unitEntries(p).length}):needsUnit(filters)?t('No captured offers match these filters.'):t(m.reason))}</p>${renderCost(p)}</section><section class="detail-section"><div class="section-heading"><h3>${t('Project facts')}</h3><small>${t('Published by sources')}</small></div><div class="facts-grid">${fact('Target handover',e(date(p.completion)))}${fact('Construction stage',e(statusLabel(p)))}${fact('Apartment sizes',p.area?.min?number(p.area.min)+(p.area.max?'–'+number(p.area.max):'+')+' '+t('m²'):t('Not published'))}${fact('Floors',e(p.floorRangePublished||p.floors||t('Not published')))}${fact('Map location',e(pinLabel(p)))}${fact('3D geometry',e(modelType(p)))}${dist!=null?fact('Distance to my place',number(dist)+' '+t('km')+'<small>'+t('Straight-line distance')+'</small>'):''}</div>${past?`<div class="note-box">${t('The target date has passed. Completion and permission to occupy are unconfirmed.')}</div>`:''}<p class="field-help">${e(tr(p.statusNote||t('A target date does not establish completion.')))}</p>${link(hasCoordinates(p)?`https://www.google.com/maps/search/?api=1&query=${p.coordinates[1]},${p.coordinates[0]}`:`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(p.address+' Yerevan')}`,t('Open in Google Maps'),'text-link')}</section>${p.amenities?.length?`<section class="detail-section"><h3>${t('Features described by sources')}</h3><ul class="fact-list">${p.amenities.map(x=>'<li>'+e(tr(x))+'</li>').join('')}</ul><p class="field-help">${t('Source claims and planned amenities have not been independently inspected.')}</p></section>`:''}<section class="detail-section"><h3>${t('Things to clarify')}</h3>${sourceNotes(p)||`<p class="field-help">${t('Confirm the unit, contract, location and construction quality.')}</p>`}</section>`;}
const variantBasis=v=>e(getLanguage()==='hy'&&v.basisHy?v.basisHy:getLanguage()==='ru'&&v.basisRu?v.basisRu:tr(v.basis||''));
function renderOffer(o,entry){return `<article class="offer-card"><div class="offer-top"><strong>${number(o.area)} ${t('m²')}</strong>${entry?`<span class="fit-badge offer">${t('Matches every apartment filter')}</span>`:''}</div><div class="offer-price">${o.priceQuality?.status==='review_required'?t('Price requires review'):money(entry?.price??o.totalAMD)}</div>${entry&&filters.budgetBasis==='total'?`<p>${t('Including planned extras')}: ${million(entry.budgetPrice)}</p>`:''}<div class="offer-facts"><span>${o.floor!=null?t('Floor {n}',{n:number(o.floor,0)}):t('Floor not published')}</span><span>${t('Unit {n}',{n:o.unit})}</span>${o.rooms?'<span>'+t('{n} rooms',{n:number(o.rooms,0)})+'</span>':''}</div><p>${e(tr(entry?.priceBasis||o.priceBasis||t('Advertised purchase price')))}</p>${o.priceVariants?.length>1?'<p>'+o.priceVariants.map(v=>variantBasis(v)+': '+money(v.totalAMD)).join('<br>')+'</p>':''}${o.floorplanUrl?`<a href="${e(safeURL(o.floorplanUrl))}" target="_blank" rel="noopener noreferrer"><img class="offer-plan" src="${e(safeURL(o.floorplanUrl))}" alt="${e(t('Published apartment floor plan'))}" loading="lazy"/></a>`:''}<p>${o.priceQuality?.status==='review_required'?t('Price requires review · excluded from matches'):t(unavailable(o)?'Marked booked / unavailable':'Not marked booked · seller confirmation needed')} · ${t('Checked {date}',{date:date(o.checkedAt,true)})}</p>${link(o.url,t('Open apartment listing'))}</article>`;}
function offersSection(p){return `<section class="detail-section"><h3>${t('Specific apartment offers')}</h3><div class="apartment-filter-context"><p>${t('These apartments use the same filters as your map and results.')}</p><button class="button light" data-filters>${t('Edit apartment filters')}</button><label class="check-row"><input id="showAllProjectUnits" type="checkbox"/><span>${t('Show all captured units in this project')}</span></label></div>${matchingEvidenceHTML(p,prefs,filters)}<p id="unitCount" class="field-help"></p><div id="unitResults"></div><p class="field-help">${t('Inventory is a dated source snapshot. Prices and availability must be confirmed with the seller.')}</p>${p.inventoryRefresh?.checkedAt?`<p class="field-help">${t('Inventory checked {date}',{date:date(p.inventoryRefresh.checkedAt,true)})} · ${t('{n} units captured',{n:number(p.offers?.length||0,0)})}</p>`:''}${p.website?link(p.website,t('Developer / project website'),'button light full'):''}</section>`;}
function sourcesSection(p){const query=encodeURIComponent(nm(p)+' '+address(p));const phones=(p.contacts?.phones||[]).filter(x=>/^[+()\d\s-]+$/.test(x));return `<section class="detail-section"><h3>${t('Sources and evidence')}</h3>${freshnessHTML(p)}<p class="field-help">${t('Checked {date}',{date:date(p.checkedAt||metadata.checkedAt,true)})}</p>${p.priceQuality?.status==='review_required'?`<div class="note-box">${t('The source publishes implausible prices. These values are excluded from affordability matching until corrected.')}</div>`:''}${p.inventoryCounts?`<div class="source-counts"><h3>${t('Published inventory counts')}</h3><p>${t('Directory summary')}: <b>${number(p.inventoryCounts.catalogue,0)}</b><br>${t('Project detail page')}: <b>${number(p.inventoryCounts.projectDetail,0)}</b><br>${t('Captured unit list')}: <b>${number(p.inventoryCounts.unitList,0)}</b></p><p class="field-help">${t('These source views can have different scopes. The figures are not reconciled and do not establish current availability.')}</p></div>`:''}${p.sources.map(sourceLink).join('')}${p.sourceComparisons?.length?`<h3>${t('Published source facts')}</h3>${p.sourceComparisons.map(s=>`<div class="source-fact">${link(s.sourceUrl,new URL(s.sourceUrl).hostname)}<p>${s.price?.min?number(s.price.min,0)+' '+s.price.currency+' '+t('/ m²'):t('Not published')} · ${t('Target handover')}: ${date(s.completion)}<br>${statusLabel(s)}</p></div>`).join('')}`:''}<div class="research-links">${link('https://www.google.com/search?q='+query,t('Search the web'))}${link('https://www.google.com/search?q='+query+'+reviews',t('Reviews'))}${link('https://www.google.com/search?q=site%3Alist.am+'+query,t('Resale listings'))}</div><p class="field-help">${t('External search links are research tools, not reviewed evidence. Publisher websites retain their own language.')}</p></section><section class="detail-section"><h3>${t('Published contacts')}</h3><div class="research-links">${phones.map(x=>`<a href="tel:${e(x.replace(/[^+\d]/g,''))}">${e(x)}</a>`).join('')}${p.contacts?.email&&/^[^\s<>@]+@[^\s<>@]+\.[^\s<>@]+$/.test(p.contacts.email)?`<a href="mailto:${e(p.contacts.email)}">${e(p.contacts.email)}</a>`:''}</div>${p.website?link(p.website,t('Developer / project website')):''}</section>${p.progressUpdates?.length?`<section class="detail-section"><h3>${t('Construction progress')}</h3>${p.progressUpdates.map(x=>`<p class="field-help">${date(x.date,true)}</p><div class="progress-gallery">${(x.images||[]).map(url=>`<a href="${e(safeURL(url))}" target="_blank" rel="noopener noreferrer"><img src="${e(safeURL(url))}" alt="${e(t('Publisher construction photo'))}" loading="lazy"/></a>`).join('')}</div>`).join('')}</section>`:''}`;}
const checks=[['unit','Apartment and floor plan','Usable area, orientation, balcony and windows'],['handover','Handover and finish','Contractual date, selected building and included work'],['permit','Permit and ownership','Review actual documents with a qualified professional'],['technical','Technical review','Structure, seismic design, insulation and workmanship'],['costs','Extra and recurring costs','Maintenance, parking, heating, renovation and fees'],['visit','Site visit','Noise, access, daylight and surroundings']];
function notesSection(p){return `<section class="detail-section"><h3>${t('Your viewing checklist')}</h3><p class="field-help">${t('Saved privately on this device')}</p>${checks.map(([key,title,desc])=>`<label class="check-row"><input type="checkbox" data-check="${key}" ${state.checks[p.id]?.[key]?'checked':''}/><span>${t(title)}<small>${t(desc)}</small></span></label>`).join('')}</section><section class="detail-section"><h3>${t('Your notes')}</h3><textarea id="projectNotes" aria-label="${e(t('Your notes'))}" placeholder="${e(t('Floor, orientation, questions for the developer…'))}">${e(state.notes[p.id]||'')}</textarea><p class="field-help">${t('Notes and favourites stay in this browser. Export a backup to move them to another device.')}</p></section>`;}
function renderDetail(p){if(!p)return;const top=$('detailPanel').scrollTop;
 $('detailPanel').innerHTML=`<div class="detail-cover">${projectImage(p,'detail-image')}<button id="closeDetail" class="icon-button detail-close" aria-label="${e(t('Close'))}">×</button><div class="detail-cover-tag">${e(t(p.district))} · ${e(statusLabel(p))}</div></div><div class="detail-content"><div class="detail-kicker">${t('PROJECT WORKSPACE')}</div><h2>${e(nm(p))}</h2><p class="detail-address">${e(address(p))}<br>${e(projectText(p,'developer')||t('Developer to confirm'))}</p><div class="detail-actions"><button class="button ${state.saved.has(p.id)?'dark':'light'}" data-save="${e(p.id)}">${icon('heart')}${t(state.saved.has(p.id)?'Saved':'Save project')}</button><button class="button ${state.compare.has(p.id)?'dark':'light'}" data-compare="${e(p.id)}">${icon('compare')}${t('Compare')}</button><button class="button light" id="shareProject" aria-label="${e(t('Copy project link'))}">${icon('link')}</button></div><button class="studio-launch" id="launchStudio"><span class="studio-cube">${icon('building')}</span><span><strong>${t('Open 3D model studio')}</strong><small>${e(modelType(p))}</small></span>${icon('arrow')}</button>${p.imageSourceUrls?.length>1?`<div class="gallery-thumbs">${p.imageSourceUrls.map((url,i)=>`<button data-image="${i}" aria-label="${e(t('Project image {n}',{n:i+1}))}"><img src="${e(safeURL(url))}" alt="${e(nm(p))}" loading="lazy"/></button>`).join('')}</div>`:''}<div class="detail-tabs" role="tablist">${[['overview','Overview'],['geometry','Map accuracy'],['offers','Apartments'],['sources','Sources'],['notes','My research']].map(([key,label])=>`<button role="tab" data-tab="${key}" aria-selected="${state.tab===key}" class="${state.tab===key?'active':''}">${t(label)}${key==='offers'&&p.offers.length?' <span>'+number(p.offers.length,0)+'</span>':''}</button>`).join('')}</div><div id="detailTab" role="tabpanel">${state.tab==='overview'?overview(p):state.tab==='geometry'?spatialSection(p,state.selectedBuilding):state.tab==='offers'?offersSection(p):state.tab==='sources'?sourcesSection(p):notesSection(p)}</div></div>`;
 $('detailPanel').hidden=false;$('detailPanel').scrollTop=top;$('closeDetail').onclick=closeDetail;$('launchStudio').onclick=()=>openStudio(p);
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;renderDetail(p);});document.querySelectorAll('[data-image]').forEach(b=>b.onclick=()=>{$('detailPanel').querySelector('.detail-image').src=p.imageSourceUrls[Number(b.dataset.image)];});
 if($('projectNotes'))$('projectNotes').oninput=ev=>{state.notes[p.id]=ev.target.value;persist();};document.querySelectorAll('[data-check]').forEach(b=>b.onchange=()=>{state.checks[p.id]||={};state.checks[p.id][b.dataset.check]=b.checked;persist();});
 if($('footprintSelect'))$('footprintSelect').onchange=ev=>{state.selectedBuilding=ev.target.value||null;renderDetail(p);updateMap();if(state.selectedBuilding)focusBuilding(p,state.selectedBuilding);};if($('focusFootprint'))$('focusFootprint').onclick=()=>focusBuilding(p,$('footprintSelect').value);
 if($('unitResults')){$('showAllProjectUnits').onchange=()=>renderUnitList(p);renderUnitList(p);}
 $('shareProject').onclick=async()=>{const url=location.origin+location.pathname+'#project='+encodeURIComponent(p.id);try{await navigator.clipboard.writeText(url);toast(t('Project link copied.'));}catch{showInfo(t('Project link'),link(url,url));}};
}
function renderUnitList(p,limit=24){const matches=unitEntries(p),all=$('showAllProjectUnits').checked,entries=all?(p.offers||[]).map(offer=>matches.find(x=>x.offer.id===offer.id)||{offer,price:offer.totalAMD,noMatch:true}):matches;entries.sort((a,b)=>(a.price??Infinity)-(b.price??Infinity));$('unitCount').textContent=t('{shown} of {total} captured offers',{shown:number(entries.length,0),total:number(p.offers?.length||0,0)});$('unitResults').innerHTML=entries.length?entries.slice(0,limit).map(x=>renderOffer(x.offer,x.noMatch?null:x)).join('')+(entries.length>limit?`<button id="moreUnits" class="button light full">${t('Show more apartments')}</button>`:''):`<p class="muted">${t('No captured offers match these filters.')}</p>`;if($('moreUnits'))$('moreUnits').onclick=()=>renderUnitList(p,limit+24);}
function selectProject(id,fly=true){const p=projects.find(p=>p.id===id);if(!p)return;popup?.remove();hoverPopup?.remove();if(state.selected!==id){state.tab='overview';state.selectedBuilding=null;}state.selected=id;history.replaceState(null,'','#project='+encodeURIComponent(id));renderDetail(p);renderResults();$('detailPanel').scrollTop=0;if(map&&hasCoordinates(p)&&fly){if(p.spatial?.footprints?.length>1){const bounds=p.spatial.footprints.map(f=>geometryBounds(f.geometry)).reduce((a,b)=>[[Math.min(a[0][0],b[0][0]),Math.min(a[0][1],b[0][1])],[Math.max(a[1][0],b[1][0]),Math.max(a[1][1],b[1][1])]]);map.fitBounds(bounds,{padding:{top:100,bottom:90,left:50,right:window.innerWidth>760?470:40},pitch:state.is3d?50:0,maxZoom:17,duration:reducedMotion?0:900});return;}map.flyTo({center:p.coordinates,zoom:16.4,pitch:state.is3d?58:0,bearing:-18,duration:reducedMotion?0:1100,padding:{right:window.innerWidth>760?Math.min(440,window.innerWidth*.38):0,left:0,top:0,bottom:0}});}}
function focusBuilding(p,id){const f=p.spatial?.footprints?.find(x=>x.id===id);if(!f||!map)return;map.flyTo({center:footprintMetrics(f.geometry).center,zoom:18,pitch:state.is3d?55:0,bearing:0,padding:{right:window.innerWidth>760?440:0,left:0,top:70,bottom:80},duration:reducedMotion?0:700});}
function closeDetail(){state.selected=null;$('detailPanel').hidden=true;history.replaceState(null,'',location.pathname+location.search);renderResults();map?.setPadding({left:0,right:0,top:0,bottom:0});}
function fitMap(){if(!map)return;const ps=filtered.filter(hasCoordinates);if(!ps.length)return toast(t('No mapped projects in these results.'));const bounds=ps.reduce((b,p)=>[[Math.min(b[0][0],p.coordinates[0]),Math.min(b[0][1],p.coordinates[1])],[Math.max(b[1][0],p.coordinates[0]),Math.max(b[1][1],p.coordinates[1])]],[[180,90],[-180,-90]]);map.fitBounds(bounds,{padding:70,maxZoom:15,duration:reducedMotion?0:800});}
function updateMap(){if(!mapReady)return;const localized=filtered.map(p=>({...p,name:nm(p)}));const fc=features(localized,prefs,state.selected,p=>currentMatch(p));fc.buildings.features=fc.buildings.features.filter(f=>modelRecords.get(f.properties.id)?.footprintId!==f.properties.buildingId);for(const f of fc.buildings.features)if(f.properties.buildingId===state.selectedBuilding&&f.properties.id===state.selected)f.properties.color='#e2a264';map.getSource('projects')?.setData(fc.points);map.getSource('project-buildings')?.setData(fc.buildings);const polygons=fc.buildings.features.map(f=>{const m=footprintMetrics(f.geometry);return [rectangleRing(m.boxCenter,m.width+6,m.depth+6,m.heading)];});map.setFilter('city-buildings',polygons.length?['!', ['within',{type:'MultiPolygon',coordinates:polygons}]]:null);map.getSource('model-hitboxes')?.setData({type:'FeatureCollection',features:filtered.filter(p=>hasCoordinates(p)&&modelRecords.has(p.id)).map(p=>modelHitFeature(modelRecords.get(p.id),p.coordinates,p.id))});mapModels?.setVisibleIds(new Set(filtered.map(p=>p.id)));}
function updateMapLanguage(){if(!mapReady)return;const lang=getLanguage();for(const layer of map.getStyle().layers){if(layer.type==='symbol'&&layer.id!=='project-labels'&&layer.layout?.['text-field']){const field=JSON.stringify(layer.layout['text-field']);if(field.includes('name'))map.setLayoutProperty(layer.id,'text-field',['coalesce',['get',lang==='en'?'name_en':'name_'+lang],['get','name:'+lang],['get','name'],['get','name_en']]);}}}
async function initMap(){try{map=new MapLibreMap({container:'map',style:'/map-style.json',center:[44.494,40.201],zoom:13.8,pitch:52,bearing:-18,maxPitch:70,minZoom:8,maxZoom:20,attributionControl:{compact:true},canvasContextAttributes:{antialias:true},dragRotate:true,touchPitch:true});map.on('load',()=>{mapReady=true;const labels=map.getStyle().layers.find(l=>l.type==='symbol')?.id;map.addLayer({id:'city-buildings',type:'fill-extrusion',source:'carto','source-layer':'building',minzoom:13,paint:{'fill-extrusion-color':'#c7cfc5','fill-extrusion-height':['max',0,['coalesce',['get','render_height'],0]],'fill-extrusion-base':['coalesce',['get','render_min_height'],0],'fill-extrusion-opacity':.8}},labels);map.addSource('reference',{type:'geojson',data:{type:'FeatureCollection',features:[]}});map.addLayer({id:'reference-radius',type:'fill',source:'reference',filter:['==',['geometry-type'],'Polygon'],paint:{'fill-color':'#cea86c','fill-opacity':.13}},labels);map.addLayer({id:'reference-outline',type:'line',source:'reference',filter:['==',['geometry-type'],'Polygon'],paint:{'line-color':'#b88b48','line-width':1.5,'line-dasharray':[3,2]}});map.addLayer({id:'reference-point',type:'circle',source:'reference',filter:['==',['geometry-type'],'Point'],paint:{'circle-color':'#b77a3a','circle-radius':8,'circle-stroke-width':3,'circle-stroke-color':'#fff'}});map.addSource('project-buildings',{type:'geojson',data:{type:'FeatureCollection',features:[]}});map.addLayer({id:'project-footprints',type:'fill',source:'project-buildings',paint:{'fill-color':['get','color'],'fill-opacity':.2}});map.addLayer({id:'project-footprint-outlines',type:'line',source:'project-buildings',paint:{'line-color':['get','color'],'line-width':2}});map.addLayer({id:'project-blocks',type:'fill-extrusion',source:'project-buildings',minzoom:13,paint:{'fill-extrusion-color':['get','color'],'fill-extrusion-height':['get','height'],'fill-extrusion-opacity':.88}});map.addSource('model-hitboxes',{type:'geojson',data:{type:'FeatureCollection',features:[]}});map.addLayer({id:'model-pick-volumes',type:'fill-extrusion',source:'model-hitboxes',minzoom:13,paint:{'fill-extrusion-height':['get','height'],'fill-extrusion-color':'#e2e7dc','fill-extrusion-opacity':.001}});map.addSource('projects',{type:'geojson',data:{type:'FeatureCollection',features:[]}});map.addLayer({id:'project-points',type:'circle',source:'projects',paint:{'circle-radius':['interpolate',['linear'],['zoom'],10,3,14,6,17,8],'circle-color':['get','color'],'circle-stroke-width':2,'circle-stroke-color':'#fff'}});map.addLayer({id:'project-labels',type:'symbol',source:'projects',minzoom:14,layout:{'text-field':['get','name'],'text-size':11,'text-font':['Open Sans Regular'],'text-offset':[0,1.5],'text-anchor':'top','text-max-width':16},paint:{'text-color':'#24473c','text-halo-color':'#fffdf5','text-halo-width':2}});map.setLight({anchor:'viewport',color:'#fff5df',intensity:.5,position:[1.5,210,35]});updateMap();updateMapLanguage();updateReference();
 map.on('click',ev=>{if(referenceMode){referenceMode=false;state.reference=[ev.lngLat.lng,ev.lngLat.lat];persist();updateReference();renderResults();if(state.selected)renderDetail(projects.find(p=>p.id===state.selected));$('mapNotice').hidden=true;return;}const items=map.queryRenderedFeatures([[ev.point.x-7,ev.point.y-7],[ev.point.x+7,ev.point.y+7]],{layers:['project-points','project-blocks','project-footprints','project-labels','model-pick-volumes']});const ids=[...new Set(items.map(f=>String(f.properties.id)))];if(ids.length===1){selectProject(ids[0]);const building=items.find(f=>f.properties.buildingId)?.properties.buildingId;if(building){state.selectedBuilding=building;state.tab='geometry';renderDetail(projects.find(p=>p.id===ids[0]));updateMap();focusBuilding(projects.find(p=>p.id===ids[0]),building);}}else if(ids.length>1){hoverPopup?.remove();popup?.remove();popup=new Popup({closeButton:true,maxWidth:'320px'}).setLngLat(ev.lngLat).setHTML('<strong>'+t('Projects at this location')+'</strong>'+ids.map(id=>'<button class="map-choice" data-open="'+e(id)+'">'+e(nm(projects.find(x=>x.id===id)))+'</button>').join('')).addTo(map);}});
 for(const layer of ['project-points','project-blocks','project-footprints','project-labels','model-pick-volumes']){map.on('mouseenter',layer,()=>map.getCanvas().style.cursor='pointer');map.on('mouseleave',layer,()=>{map.getCanvas().style.cursor='';hoverPopup?.remove();});}map.on('mousemove','project-points',ev=>{const p=projects.find(x=>x.id===String(ev.features?.[0]?.properties.id));if(!p||popup?.isOpen())return;hoverPopup?.remove();hoverPopup=new Popup({closeButton:false,offset:15}).setLngLat(p.coordinates).setHTML('<strong>'+e(nm(p))+'</strong><br>'+priceLabel(p)+'<br>'+e(pinLabel(p))).addTo(map);});if(state.selected)selectProject(state.selected);if(modelRecords.size)loadMapModels();});
 map.on('error',()=>{if(!mapReady){$('mapNotice').hidden=false;$('mapNotice').textContent=t('Map resources are unavailable. The project list and comparison still work.');}});
 }catch{$('mapNotice').hidden=false;$('mapNotice').textContent=t('3D is unavailable on this device. Use the project list.');toggleMobile(true);}}
async function loadMapModels(){if(!mapReady)return;if(!mapModelsLoading)mapModelsLoading=import('./map-models.js').then(({MapModels})=>{mapModels=new MapModels(map);map.addLayer(mapModels.layer,'project-points');});await mapModelsLoading;for(const [id,record]of modelRecords){const p=projects.find(x=>x.id===id);if(p&&hasCoordinates(p))await mapModels.add(id,record,p.coordinates).catch(()=>toast(t('A saved model could not be loaded.')));}mapModels.setVisibleIds(new Set(filtered.map(p=>p.id)));mapModels.enabled=state.is3d&&$('projectModelsToggle').checked;updateMap();}
function updateReference(){if(mapReady)map.getSource('reference')?.setData(state.reference?radiusGeoJSON(state.reference):{type:'FeatureCollection',features:[]});$('referenceBadge').hidden=!state.reference;$('referenceBadge').innerHTML=state.reference?'<span>'+t('My reference place · 1 km radius')+'</span><button id="clearReference" aria-label="'+e(t('Remove reference location'))+'">×</button>':'';if($('clearReference'))$('clearReference').onclick=()=>{state.reference=null;filters.radiusKm=null;persist();updateReference();renderResults();if(state.selected)renderDetail(projects.find(p=>p.id===state.selected));};}
function setMapMode(on){state.is3d=on;$('view3d').classList.toggle('active',on);$('view2d').classList.toggle('active',!on);$('view3d').setAttribute('aria-pressed',on);$('view2d').setAttribute('aria-pressed',!on);map?.easeTo({pitch:on?55:0,bearing:on?-18:0,duration:reducedMotion?0:650});updateLayers();}
function updateLayers(){if(!mapReady)return;for(const [layer,on]of [['project-footprints',$('projectModelsToggle').checked],['project-footprint-outlines',$('projectModelsToggle').checked],['city-buildings',state.is3d&&$('cityBuildingsToggle').checked],['project-blocks',state.is3d&&$('projectModelsToggle').checked],['model-pick-volumes',state.is3d&&$('projectModelsToggle').checked],['project-labels',$('labelsToggle').checked],['reference-radius',$('radiusToggle').checked],['reference-outline',$('radiusToggle').checked]])map.setLayoutProperty(layer,'visibility',on?'visible':'none');if(mapModels){mapModels.enabled=state.is3d&&$('projectModelsToggle').checked;map.triggerRepaint();}}
function openPreferences(){const f=$('preferencesForm');for(const[k,v]of Object.entries(prefs))if(f.elements[k]){if(typeof v==='boolean')f.elements[k].checked=v;else f.elements[k].value=v;}$('preferencesError').textContent='';showDialog('preferencesDialog');}
function showComparison(){const list=[...state.compare].map(id=>projects.find(p=>p.id===id)).filter(Boolean);if(list.length<2)return toast(t('Choose two to four projects to compare.'));const rows=[['Search match',p=>fitBadge(p)],['Starting price / m²',p=>priceRange(p)],['Total-cost scenario',p=>{const c=costScenario(p,prefs,filters);return c?million(c.total)+'<small>'+number(c.area)+' '+t('m²')+' · '+t(c.offer?'Published offer':'Rate estimate')+'</small>':t('Quote needed');}],['Target handover',p=>date(p.completion)],['Construction stage',statusLabel],['Floors',p=>e(p.floorRangePublished||p.floors||t('Not published'))],['Matching offers',p=>number(unitEntries(p).length,0)],['Distance to my place',p=>{const d=distanceKm(state.reference,p.coordinates);return d==null?t('Set a reference place'):number(d)+' '+t('km')+'<small>'+t('Straight-line distance')+'</small>';}],['Location',p=>e(address(p))+'<small>'+e(pinLabel(p))+'</small>'],['Things to clarify',p=>sourceNotes(p)||t('Confirm the unit, contract, location and construction quality.')],['Your notes',p=>e(state.notes[p.id]||t('No notes yet'))],['Sources',p=>p.sources.slice(0,3).map(sourceLink).join('')]];$('compareContent').innerHTML=`<p>${t('Published evidence and your cost assumptions. No construction-quality score is inferred.')}</p><div class="comparison-scroll"><table class="comparison-table"><thead><tr><th>${t('Details')}</th>${list.map(p=>`<th>${projectImage(p,'compare-image')}<strong>${e(nm(p))}</strong><small>${e(t(p.district))}</small></th>`).join('')}</tr></thead><tbody>${rows.map(([label,fn])=>'<tr><td>'+t(label)+'</td>'+list.map(p=>'<td>'+fn(p)+'</td>').join('')+'</tr>').join('')}</tbody></table></div><button id="exportComparison" class="button light">${t('Export comparison CSV')}</button>`;$('exportComparison').onclick=()=>exportCSV(list);showDialog('compareDialog');}
function exportCSV(items){const headers=['Project','District','Address','Starting price / m²','Currency','Target handover','Construction stage','Search match','Total-cost scenario','Distance to my place','Your notes','Sources'].map(t);const rows=items.map(p=>[nm(p),t(p.district),address(p),rateAMD(p,prefs)?p.price?.min:null,p.price?.currency,date(p.completion),statusLabel(p),t(currentMatch(p).label),costScenario(p,prefs,filters)?.total,distanceKm(state.reference,p.coordinates),state.notes[p.id],p.sources.map(s=>s.url).join(' | ')]);download('\uFEFF'+[headers,...rows].map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8','yerevan-atlas-'+getLanguage()+'.csv');}
function showDataHealth(){showInfo(t('Data health'),evidenceHTML(filtered,metadata));$('exportEvidence').onclick=()=>download(JSON.stringify(evidenceReport(filtered,metadata),null,2),'application/json','yerevan-atlas-evidence.json');}
function showCoverage(){showInfo(t('About this atlas'),`<div class="coverage-stats"><div><strong>${number(metadata.yerevan,0)}</strong><small>${t('Yerevan records')}</small></div><div><strong>${number(metadata.offers,0)}</strong><small>${t('captured offers')}</small></div><div><strong>11</strong><small>${t('districts')}</small></div></div><p>${t('Research snapshot: {date}. This catalogue is not an exhaustive official building register.',{date:date(metadata.checkedAt,true)})}</p><h3>${t('Coverage')}</h3><p>${t('{karu} Karucapatoxic and {myhome} MyHome records were re-read. Reviewed duplicates are merged; separate blocks and source inventories remain separate.',{karu:metadata.sourceRecords.Karucapatoxic,myhome:metadata.sourceRecords.MyHome})}</p><p>${t('{units} apartment listings: {myhome} from all public MyHome unit-list pages, plus {official} selected developer listings. No price or size restriction was applied to MyHome collection.',{units:metadata.offers,myhome:metadata.offerSearchScope.myhomeApartments,official:metadata.offerSearchScope.officialUnits})}</p><p>${t('Public unit lists do not cover every physical apartment. Houses and townhouses are excluded from apartment inventory. Only selected units have detailed finish, balcony and building-height evidence.')}</p><p>${t('All {n} catalogue records were parsed successfully. {failed} direct developer requests failed; their previous facts were not silently marked fresh.',{n:metadata.refresh.catalogueSuccesses,failed:metadata.refresh.officialDirectFetchFailures})}</p><p>${link(location.origin+'/data/refresh-audit.json',t('Download the source refresh audit'))}</p><h3>${t('Geometry and evidence')}</h3><p>${t('Coloured footprints follow manually matched OpenStreetMap buildings. Unmatched projects remain points. Heights use source values or an explicit floor-count estimate. Photo models are optional visual approximations.')}</p><h3>${t('Your data')}</h3><p>${t('Preferences, favourites, notes and reference locations stay in this browser. Image models and imported GLB files are stored on this device. They do not sync automatically. Model files are exported separately from the research backup.')}</p><div class="import-export"><button id="backupExport" class="button light">${t('Export my research')}</button><label class="button light" for="backupImport">${t('Import backup')}</label><input id="backupImport" class="backup-input" type="file" accept="application/json"/></div><h3>${t('Sources')}</h3><p>${link('https://karucapatoxic.am/','Karucapatoxic')} · ${link('https://myhome.am/en/buildings','MyHome')} · ${link('https://www.cba.am/en/exchange-rates-archive/',t('CBA exchange rates'))}</p><p>© OpenStreetMap contributors · © CARTO</p><p>${t('Publisher photos remain the property of their owners. Map labels and external websites follow their providers’ language coverage.')}</p>`);$('backupExport').onclick=()=>download(JSON.stringify({version:3,...JSON.parse(localStorage.getItem(STORE)||'{}')},null,2),'application/json','yerevan-atlas-research.json');$('backupImport').onchange=async ev=>{try{const file=ev.target.files[0];if(!file||file.size>2e6)throw Error();const b=parseResearchBackup(await file.text());if(!b)throw Error();prefs={...prefs,...b.prefs};state.saved=new Set(b.saved.filter(id=>projects.some(p=>p.id===id)));state.compare=new Set((b.compare||[]).filter(id=>projects.some(p=>p.id===id)).slice(0,4));state.notes=b.notes&&typeof b.notes==='object'?b.notes:{};state.checks=b.checks&&typeof b.checks==='object'?b.checks:{};filters=normalizeFilters(b.filters);savedSearches=Array.isArray(b.savedSearches)?b.savedSearches.filter(s=>typeof s.name==='string'&&parseSearch(s.search)).slice(0,20):[];state.reference=Array.isArray(b.reference)&&hasCoordinates({coordinates:b.reference})?b.reference:null;setLanguage(b.locale||getLanguage());persist();localize();renderResults();$('infoDialog').close();toast(t('Research backup imported.'));}catch{toast(t('This file is not a valid research backup.'));}};}
function showGeometry(){const stats=spatialStats(projects);showInfo(t('Model accuracy'),`<div class="coverage-stats"><div><strong>${number(stats.buildings,0)}</strong><small>${t('Mapped footprints')}</small></div><div><strong>${number(stats.records,0)}</strong><small>${t('Project records')}</small></div></div><p>${t('Footprint matches use source addresses or names. Nearby buildings are never snapped automatically to project pins.')}</p><p>${t('A single photo cannot reveal hidden surfaces, true depth or exact scale. Photo-based models are visual reconstructions, not surveyed architectural models.')}</p><ul><li>${t('City buildings: OpenStreetMap footprints with source heights or visual estimates.')}</li><li>${t('Project points locate source records. Only matched building polygons receive footprint dimensions; missing heights stay flat.')}</li><li>${t('Image studio: selected facade corners are perspective-corrected and applied to a dimensioned model. You control dimensions and alignment.')}</li><li>${t('GLB import: use an architect’s model or a calibrated multi-view reconstruction. Check scale, orientation and placement before relying on it.')}</li></ul>`);}
async function openStudio(p){toast(t('Opening 3D studio…'));try{const {openStudio}=await import('./studio.js');await openStudio({project:p,preset:presets.find(x=>x.projectId===p.id),record:modelRecords.get(p.id),onSave:async record=>{modelRecords.set(p.id,record);await loadMapModels();renderDetail(p);renderResults();toast(t('Model saved on this device and placed on the map.'));},onRemove:()=>{modelRecords.delete(p.id);mapModels?.remove(p.id);loadMapModels();renderDetail(p);renderResults();}});}catch(error){console.error(error);toast(t('The 3D studio could not open on this device.'));}}
function toggleMobile(open){const on=typeof open==='boolean'?open:!$('sidebar').classList.contains('mobile-open');$('sidebar').classList.toggle('mobile-open',on);$('mobileResults').innerHTML=icon(on?'pin':'list')+'<span>'+t(on?'Back to map':'View projects')+'</span>';}
function resetFilters(){filters=normalizeFilters();state.query='';state.sort='match';prefs.nearby=false;state.footprintsOnly=false;$('footprintsOnlyToggle').checked=false;$('searchInput').value='';$('sortSelect').value='match';persist();renderResults();if(state.selected)renderDetail(projects.find(p=>p.id===state.selected));}
function localize(){translateDOM();$('languageSelect').value=getLanguage();for(const p of projects){p._searchText=[nm(p),address(p),projectText(p,'developer')].join(' ');p._developerLabel=projectText(p,'developer');}$('checkedLabel').textContent=t('Snapshot {date}',{date:date(metadata.snapshotAt||metadata.checkedAt,true)});$('fxReference').textContent=t('CBA reference: {rate} AMD/USD · {date}. Your planning rate can differ.',{rate:number(metadata.fx?.USDAMD),date:date(metadata.fx?.date,true)});document.title=t('Yerevan Atlas · Find your home');renderResults();renderSavedSearches();updateReference();updateMapLanguage();if(state.selected)renderDetail(projects.find(p=>p.id===state.selected));if($('compareDialog').open)showComparison();if($('infoDialog').open)$('infoDialog').close();if($('filtersDialog').open)openFilters();}
function renderActiveFilters(){const items=activeFilterItems(filters,prefs);$('activeFilterCount').textContent=number(items.length,0);$('activeFilters').innerHTML=items.map((x,i)=>`<button class="active-filter" data-remove-filter="${i}" title="${e(t('Remove filter'))}">${e(x.key==='developers'?projects.find(p=>p.developer===x.value)?._developerLabel||x.label:x.label)}<span>×</span></button>`).join('')+(items.length?`<button class="clear-filters" data-reset>${t('Clear all')}</button>`:'');$('footprintsOnlyToggle').checked=filters.location==='footprint';}
function removeFilter(key,value){if(['nearby','includeUnknown'].includes(key))prefs[key]=false;else if(Array.isArray(filters[key]))filters[key]=filters[key].filter(x=>x!==value);else filters[key]=FILTER_DEFAULTS[key];persist();renderResults();if(state.selected)renderDetail(projects.find(p=>p.id===state.selected));}
function relaxSuggestions(){
 const items=activeFilterItems(filters,prefs),seen=new Set(),suggestions=[];
 const groups={districts:'District',statuses:'Construction stage',developers:'Developer',rooms:'Rooms',finishes:'Finish at this price'};
 for(const x of items){
  if(seen.has(x.key)||x.key==='nearby'||x.key==='includeUnknown')continue;seen.add(x.key);
  const draft=normalizeFilters(filters);draft[x.key]=FILTER_DEFAULTS[x.key];
  const count=searchProjects(projects,state,prefs,draft).length;
  if(count)suggestions.push({key:x.key,label:groups[x.key]?t(groups[x.key]):x.label,count});
 }
 let html=suggestions.sort((a,b)=>b.count-a.count).slice(0,3).map(x=>`<button class="relax-filter" data-relax="${x.key}">${e(t('Without {filter}: {n} projects',{filter:x.label,n:number(x.count,0)}))}</button>`).join('');
 if(state.query){const count=searchProjects(projects,{...state,query:''},prefs,filters).length;if(count)html+=`<button class="relax-filter" data-clear-query>${e(t('Without search text: {n} projects',{n:number(count,0)}))}</button>`;}
 return html;
}
function openFilters(draft=filters,draftPrefs=prefs){$('filtersDialog').innerHTML=filterDialogHTML(projects,state,draftPrefs,draft);$('filtersDialog').querySelector('h2').id='filtersDialogTitle';showDialog('filtersDialog');$('closeFilters').onclick=()=>$('filtersDialog').close();$('resetFilterDraft').onclick=()=>openFilters(normalizeFilters(),{...prefs,nearby:false});const form=$('filtersForm');const update=()=>{const d=readFilterForm(form,draftPrefs),valid=validPreferences(d.prefs)&&(d.filters.floorMin==null||d.filters.floorMax==null||d.filters.floorMin<=d.filters.floorMax)&&form.checkValidity();$('filterError').textContent=valid?'':t('Use valid positive ranges and keep each minimum below its maximum.');$('applyFilters').disabled=!valid;if(!valid)return;const list=searchProjects(projects,state,d.prefs,d.filters);$('filterPreviewCount').textContent=t('{n} projects',{n:number(list.length,0)});$('filterPreviewUnits').textContent=t('{n} published apartments meet all selected criteria',{n:number(list.reduce((n,p)=>n+matchingOfferEntries(p,d.prefs,d.filters).length,0),0)});for(const key of ['districts','statuses','rooms','developers','finishes']){const counts=facetCounts(projects,state,d.prefs,d.filters,key);document.querySelectorAll(`[data-count-key="${key}"]`).forEach(el=>{const n=counts[el.dataset.countValue]||0;el.textContent=number(n,0);const input=el.closest('label').querySelector('input');input.disabled=n===0&&!input.checked;});}};form.oninput=update;form.onchange=ev=>{if(ev.target.name==='mode'&&ev.target.value==='units'){form.elements.useBudget.checked=true;form.elements.useArea.checked=true;}update();};form.onsubmit=ev=>{ev.preventDefault();update();if($('applyFilters').disabled)return;const d=readFilterForm(form,draftPrefs);prefs=d.prefs;filters=d.filters;persist();$('filtersDialog').close();renderResults();if(state.selected)renderDetail(projects.find(p=>p.id===state.selected));};$('developerSearch').oninput=ev=>{ev.stopPropagation();const query=ev.target.value.toLocaleLowerCase();document.querySelectorAll('[data-facet="developers"] label').forEach(el=>el.hidden=!el.textContent.toLocaleLowerCase().includes(query));};update();}
function renderSavedSearches(selected=''){$('savedSearchSelect').innerHTML=`<option value="">${t('Saved searches')}</option>`+savedSearches.map(x=>`<option value="${e(x.id)}">${e(x.name)}</option>`).join('');$('savedSearchSelect').value=selected;$('deleteSearch').hidden=!selected;}
function restoreSearch(payload){const search=parseSearch(payload);if(!search||!validPreferences({...prefs,...search.prefs}))return false;prefs={...prefs,...search.prefs};filters=search.filters;state.query=search.query;state.sort=['match','price','unitPrice','date','distance','freshness','name'].includes(search.sort)?search.sort:'match';state.reference=search.reference;$('searchInput').value=state.query;$('sortSelect').value=state.sort;persist();refreshSearchResults();updateReference();return true;}
async function shareSearch(){const url=new URL(location.origin+location.pathname);url.searchParams.set('search',JSON.stringify(searchPayload(state,prefs,filters)));try{await navigator.clipboard.writeText(url.href);toast(t('Search link copied. It includes filters, not your private notes.'));}catch{showInfo(t('Share this search'),`<p>${t('This link includes search criteria and your reference point. Your private notes are excluded.')}</p><input class="share-url" readonly value="${e(url.href)}" aria-label="${e(t('Search link'))}"/>`);}}
function saveCurrentSearch(){showInfo(t('Save this search'),`<form id="saveSearchForm"><label class="filter-field"><span>${t('Search name')}</span><input id="searchName" type="text" maxlength="60" required placeholder="${e(t('My next home'))}"/></label><button class="button dark" type="submit">${t('Save search on this device')}</button></form>`);$('saveSearchForm').onsubmit=ev=>{ev.preventDefault();const name=$('searchName').value.trim();if(!name)return;const item={id:String(Date.now()),name,search:searchPayload(state,prefs,filters)};savedSearches=[item,...savedSearches].slice(0,20);persist();$('infoDialog').close();renderSavedSearches(item.id);toast(t('Search saved. Reopening it uses the latest loaded inventory.'));};$('searchName').focus();}
hydrateIcons();translateDOM();
document.addEventListener('click',ev=>{const save=ev.target.closest('[data-save]'),cmp=ev.target.closest('[data-compare]'),open=ev.target.closest('[data-open]');if(save)toggleSave(save.dataset.save);else if(cmp)toggleCompare(cmp.dataset.compare);else if(open)selectProject(open.dataset.open);if(ev.target.closest('[data-clear-query]')){state.query='';$('searchInput').value='';refreshSearchResults();}if(ev.target.closest('[data-reset]'))resetFilters();if(ev.target.closest('[data-preferences]'))openPreferences();if(ev.target.closest('[data-filters]'))openFilters();const remove=ev.target.closest('[data-remove-filter]');if(remove){const item=activeFilterItems(filters,prefs)[Number(remove.dataset.removeFilter)];if(item)removeFilter(item.key,item.value);}const relax=ev.target.closest('[data-relax]');if(relax)removeFilter(relax.dataset.relax);});
document.addEventListener('error',ev=>{if(ev.target instanceof HTMLImageElement){ev.target.style.display='none';ev.target.parentElement.classList.add('image-unavailable');}},true);
$('searchInput').oninput=ev=>{state.query=ev.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(refreshSearchResults,120);};$('searchInput').onkeydown=ev=>{if(ev.key==='Enter'){clearTimeout(searchTimer);refreshSearchResults();}};$('sortSelect').onchange=ev=>{state.sort=ev.target.value;renderResults();};$('matchToggle').onclick=()=>{const on=!(filters.useBudget&&filters.useArea);filters.useBudget=filters.useArea=on;persist();refreshSearchResults();};$('preferredToggle').onclick=()=>{filters.districts=filters.districts.length===2&&filters.districts.includes('Ajapnyak')&&filters.districts.includes('Arabkir')?[]:['Ajapnyak','Arabkir'];persist();refreshSearchResults();};$('offersToggle').onclick=()=>{filters.mode=filters.mode==='units'?'projects':'units';if(filters.mode==='units')filters.useBudget=filters.useArea=true;persist();refreshSearchResults();};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;renderResults();if(window.innerWidth<761)toggleMobile(true);});['preferencesButton','editPreferences'].forEach(id=>$(id).onclick=openPreferences);$('filtersButton').onclick=()=>openFilters();$('saveSearch').onclick=saveCurrentSearch;$('shareSearch').onclick=shareSearch;$('savedSearchSelect').onchange=ev=>{const item=savedSearches.find(x=>x.id===ev.target.value);if(item)restoreSearch(item.search);$('deleteSearch').hidden=!item;};$('deleteSearch').onclick=()=>{savedSearches=savedSearches.filter(x=>x.id!==$('savedSearchSelect').value);persist();renderSavedSearches();};
$('preferencesForm').onsubmit=ev=>{ev.preventDefault();const fd=new FormData(ev.target),p={};for(const k of ['budgetMin','budgetMax','areaMin','areaMax','fx','renovation','parking','feePercent'])p[k]=Number(fd.get(k));for(const k of ['nearby','includeUnknown'])p[k]=fd.get(k)==='on';if(!validPreferences(p)||['renovation','parking','feePercent'].some(k=>!Number.isFinite(p[k])||p[k]<0)||p.feePercent>100){$('preferencesError').textContent=t('Use valid positive ranges and keep each minimum below its maximum.');return;}prefs=p;persist();$('preferencesDialog').close();renderResults();if(state.selected)renderDetail(projects.find(p=>p.id===state.selected));};
document.querySelectorAll('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('languageSelect').onchange=ev=>{setLanguage(ev.target.value);persist();localize();};$('coverageButton').onclick=showCoverage;$('dataHealthButton').onclick=showDataHealth;$('geometryButton').onclick=showGeometry;['compareTop','openCompare'].forEach(id=>$(id).onclick=showComparison);$('clearCompare').onclick=()=>{state.compare.clear();persist();renderResults();};$('exportButton').onclick=()=>exportCSV(filtered);$('fitMap').onclick=fitMap;$('zoomIn').onclick=()=>map?.zoomIn();$('zoomOut').onclick=()=>map?.zoomOut();$('resetNorth').onclick=()=>map?.easeTo({bearing:0,duration:reducedMotion?0:500});$('view3d').onclick=()=>setMapMode(true);$('view2d').onclick=()=>setMapMode(false);$('mobileResults').onclick=()=>toggleMobile();$('layersButton').onclick=()=>$('mapLayers').hidden=!$('mapLayers').hidden;['cityBuildingsToggle','projectModelsToggle','labelsToggle','radiusToggle'].forEach(id=>$(id).onchange=updateLayers);$('footprintsOnlyToggle').onchange=ev=>{filters.location=ev.target.checked?'footprint':'all';persist();renderResults();};$('referenceButton').onclick=()=>{referenceMode=!referenceMode;$('mapNotice').hidden=!referenceMode;$('mapNotice').textContent=t('Click the map to set your workplace or another reference location.');};$('fullscreenButton').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast(t('Fullscreen is unavailable in this browser.'));}};
document.addEventListener('keydown',ev=>{if(ev.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)){ev.preventDefault();if(window.innerWidth<761)toggleMobile(true);$('searchInput').focus();}if(ev.key==='Escape'&&!document.querySelector('dialog[open]')){referenceMode=false;$('mapNotice').hidden=true;closeDetail();}});
async function boot(){try{const responses=await Promise.all([fetch('/data/projects.json').then(r=>{if(!r.ok)throw Error();return r.json();}),loadTranslations(),fetch('/data/model-presets.json').then(r=>r.ok?r.json():[]),fetch('/data/project-geometry.json').then(r=>{if(!r.ok)throw Error();return r.json();})]);projects=responses[0].projects;metadata=responses[0].metadata;presets=responses[2];projects=applySpatialData(projects,responses[3]);if(!cached.prefs?.fx&&metadata.fx?.USDAMD)prefs.fx=metadata.fx.USDAMD;if(!Array.isArray(projects)||!projects.length)throw Error();state.saved=new Set([...state.saved].filter(id=>projects.some(p=>p.id===id)));state.compare=new Set([...state.compare].filter(id=>projects.some(p=>p.id===id)));localize();const search=new URLSearchParams(location.search).get('search');if(search&&!restoreSearch(search))toast(t('This search link is invalid. Default filters are shown.'));const id=new URLSearchParams(location.hash.slice(1)).get('project');if(id)selectProject(id,false);await initMap();import('./model-store.js').then(m=>m.allModels()).then(records=>{for(const r of records){const p=projects.find(p=>p.id===r.projectId);if(p&&!r.preset)modelRecords.set(r.projectId,migrateModel(r,p));}if(modelRecords.size){loadMapModels();if(state.selected)renderDetail(projects.find(p=>p.id===state.selected));}}).catch(()=>{});}catch(err){console.error(err);$('resultCount').textContent=t('Unable to load projects');$('resultsList').innerHTML='<div class="empty-state"><h3>'+t('Could not load the catalogue.')+'</h3><button id="reloadData" class="button dark">'+t('Try again')+'</button></div>';$('reloadData').onclick=()=>location.reload();}}
boot();
